import type { Metadata } from "next";
import { brandName, type Card } from "./data";
import { absoluteUrl, site } from "./site";
import { languageAlternates, localizedUrl } from "@/i18n/paths";
import { defaultLocale, locales as allLocales, ogLocales, type Locale } from "@/i18n/routing";

/**
 * Generated by `src/app/opengraph-image.tsx`. Referenced explicitly because a
 * page-level `openGraph` object replaces the layout's, which would otherwise
 * drop the file-convention image from every page that sets its own metadata.
 */
export const ogImage = {
  path: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Rituel Cards — independent crypto card comparison",
} as const;

type SeoInput = {
  title: string;
  description: string;
  path: string;
  keywords?: string[];
  noIndex?: boolean;
  image?: { url: string; width: number; height: number; alt: string };
  article?: { publishedTime: string; modifiedTime?: string; authors?: string[]; tags?: string[] };
  /** Active locale; `path` stays locale-free ("/compare"). */
  locale?: string;
  /** Locales this page exists in, for hreflang (defaults to all). */
  availableLocales?: readonly Locale[];
};

/** Search results show ~60 characters; past that the " | Rituel Cards" suffix only gets cut off. */
const MAX_TITLE_LENGTH = 65;

/** Appends "— N Cards Compared" only while the title still fits in search results. */
export function titleWithCount(title: string, count: number): string {
  const withCount = `${title} — ${count} ${count === 1 ? "Card" : "Cards"} Compared`;
  return withCount.length <= MAX_TITLE_LENGTH ? withCount : title;
}

/** Share image rendered by a route's own `opengraph-image.tsx`. */
export function routeOgImage(path: string, alt: string) {
  return { url: absoluteUrl(`${path.replace(/\/$/, "")}/opengraph-image`), width: ogImage.width, height: ogImage.height, alt };
}

export function buildMetadata({
  title,
  description,
  path,
  keywords,
  noIndex,
  image,
  article,
  locale = defaultLocale,
  availableLocales = allLocales,
}: SeoInput): Metadata {
  const url = localizedUrl(locale, path);
  const pageTitle: Metadata["title"] =
    `${title} | ${site.name}`.length > MAX_TITLE_LENGTH ? { absolute: title } : title;
  const shareImage = image ?? {
    url: absoluteUrl(ogImage.path),
    width: ogImage.width,
    height: ogImage.height,
    alt: ogImage.alt,
  };
  return {
    title: pageTitle,
    description,
    keywords,
    alternates: { canonical: url, languages: noIndex ? undefined : languageAlternates(path, availableLocales) },
    robots: noIndex ? { index: false, follow: false } : undefined,
    openGraph: {
      title,
      description,
      url,
      siteName: site.name,
      locale: ogLocales[locale as Locale] ?? "en_US",
      images: [shareImage],
      ...(article ? { type: "article" as const, ...article } : { type: "website" as const }),
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      creator: site.twitter,
      images: [shareImage.url],
    },
  };
}

export function breadcrumbJsonLd(items: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

/** Dataset schema for the master comparison set — targets Google Dataset Search. */
export function datasetJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "Dataset",
    name: "Crypto card comparison dataset",
    description:
      "Verified fee, reward, limit and availability data for crypto debit and credit cards, re-checked against issuer documentation on a rolling basis.",
    url: absoluteUrl("/"),
    keywords: ["crypto card", "bitcoin debit card", "card fees", "cashback rates", "KYC requirements"],
    creator: {
      "@type": "Organization",
      name: "Rituel",
      url: absoluteUrl("/"),
    },
    distribution: {
      "@type": "DataDownload",
      contentUrl: absoluteUrl("/llms-full.txt"),
      encodingFormat: "text/plain",
    },
    dateModified: new Date().toISOString().slice(0, 10),
    isAccessibleForFree: true,
  };
}

export function itemListJsonLd(name: string, cards: { name: string; slug: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "ItemList",
    name,
    numberOfItems: cards.length,
    itemListElement: cards.map((card, index) => ({
      "@type": "ListItem",
      position: index + 1,
      url: absoluteUrl(`/crypto-card/${card.slug}`),
      name: card.name,
    })),
  };
}

export function faqJsonLd(faqs: { q: string; a: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqs.map((faq) => ({
      "@type": "Question",
      name: faq.q,
      acceptedAnswer: { "@type": "Answer", text: faq.a },
    })),
  };
}

/**
 * Editorial score is deliberately not exposed as `aggregateRating`: that markup
 * asserts real customer reviews, and inventing them risks a structured-data
 * penalty. The score stays visible on the page as editorial commentary.
 */
export function financialProductNode(card: {
  name: string;
  slug: string;
  description: string;
  issuerName: string;
  regionLabel: string;
  annualFeeUsd: number;
  issuanceFeeUsd: number;
  fxFeePct: number;
  atmFeePct?: number;
  atmFeeNote?: string;
  cashbackMinPct?: number;
  cashbackMaxPct?: number;
  balanceYieldApyPct?: number;
  ratingScore: number;
  lastVerifiedAt?: string | null;
  cardImageUrl?: string | null;
  officialUrl?: string | null;
  website?: string | null;
}) {
  const url = absoluteUrl(`/crypto-card/${card.slug}`);
  const rawProviderUrl = card.officialUrl || card.website || undefined;
  const providerUrl = rawProviderUrl
    ? rawProviderUrl.startsWith("http")
      ? rawProviderUrl
      : `https://${rawProviderUrl}`
    : undefined;
  const atmFee = card.atmFeeNote || (card.atmFeePct != null ? `${card.atmFeePct}%` : undefined);
  const cashbackPct = card.cashbackMaxPct ?? card.cashbackMinPct ?? 0;
  // `interestRate` is the closest schema.org has to a reward rate; unitText keeps it honest.
  const interestRate =
    cashbackPct > 0
      ? { "@type": "QuantitativeValue", value: cashbackPct, unitText: "% cashback" }
      : card.balanceYieldApyPct && card.balanceYieldApyPct > 0
        ? { "@type": "QuantitativeValue", value: card.balanceYieldApyPct, unitText: "% APY" }
        : undefined;
  return {
    "@type": "FinancialProduct",
    "@id": `${url}#product`,
    name: card.name,
    description: card.description,
    url,
    image: card.cardImageUrl ? (card.cardImageUrl.startsWith("http") ? card.cardImageUrl : absoluteUrl(card.cardImageUrl)) : undefined,
    category: "Crypto debit and credit card",
    brand: { "@type": "Brand", name: brandName(card) },
    provider: { "@type": "Organization", name: card.issuerName, url: providerUrl },
    areaServed: card.regionLabel,
    feesAndCommissionsSpecification:
      `Issuance fee $${card.issuanceFeeUsd}; annual fee $${card.annualFeeUsd}; FX fee ${card.fxFeePct}%` +
      (atmFee ? `; ATM fee ${atmFee}` : "") +
      ".",
    interestRate,
    offers: {
      "@type": "Offer",
      price: card.issuanceFeeUsd,
      priceCurrency: "USD",
      availability: "https://schema.org/InStock",
      url,
    },
    // A single editorial review (not aggregateRating), so it reflects what the page actually shows.
    review: {
      "@type": "Review",
      name: `${card.name} review`,
      author: { "@id": absoluteUrl("/#organization"), "@type": "Organization", name: site.name, url: site.url },
      publisher: { "@type": "Organization", name: site.name, url: site.url },
      datePublished: card.lastVerifiedAt || undefined,
      reviewRating: { "@type": "Rating", ratingValue: card.ratingScore, bestRating: 10, worstRating: 0 },
    },
  };
}

export function financialProductJsonLd(card: Parameters<typeof financialProductNode>[0]) {
  return { "@context": "https://schema.org", ...financialProductNode(card) };
}

export function organizationJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "Organization",
    "@id": absoluteUrl("/#organization"),
    name: site.name,
    url: site.url,
    logo: absoluteUrl("/icon.png"),
    description: site.description,
    email: site.email,
    sameAs: site.socialLinks.length > 0 ? site.socialLinks : undefined,
  };
}

export function personJsonLd(author: { name: string; slug: string; role?: string; bio?: string; imageUrl?: string; links?: string[] }) {
  return {
    "@type": "Person",
    "@id": absoluteUrl(`/blog/author/${author.slug}#person`),
    name: author.name,
    url: absoluteUrl(`/blog/author/${author.slug}`),
    jobTitle: author.role || undefined,
    description: author.bio || undefined,
    image: author.imageUrl,
    sameAs: author.links && author.links.length > 0 ? author.links : undefined,
    worksFor: { "@id": absoluteUrl("/#organization"), "@type": "Organization", name: site.name, url: site.url },
  };
}

/**
 * One `@graph` payload per article. Organization/WebSite carry site-wide `@id`s;
 * every post-scoped node (page, breadcrumb, article, products, FAQs) hangs off
 * the canonical URL so crawlers read them as a single interlinked entity set.
 */
export function articleGraphJsonLd({
  post,
  cards = [],
  faqs = [],
}: {
  post: {
    title: string;
    slug: string;
    excerpt: string;
    publishedAt: string;
    updatedAt: string;
    imageUrl?: string;
    author?: Parameters<typeof personJsonLd>[0];
  };
  cards?: Card[];
  faqs?: { question: string; answer: string }[];
}) {
  const orgId = absoluteUrl("/#organization");
  const websiteId = absoluteUrl("/#website");
  const pageUrl = absoluteUrl(`/blog/${post.slug}`);
  const articleId = `${pageUrl}#article`;
  const image = post.imageUrl ?? absoluteUrl(ogImage.path);
  const authorNode = post.author ? personJsonLd(post.author) : undefined;
  const productId = (slug: string) => `${absoluteUrl(`/crypto-card/${slug}`)}#product`;

  return {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "Organization",
        "@id": orgId,
        name: site.name,
        legalName: site.name,
        url: site.url,
        email: site.email,
        logo: absoluteUrl("/icon.png"),
        description: site.description,
        disambiguatingDescription:
          "Rituel.xyz (Rituel Cards) is an independent Web3 debit card, stablecoin payment rail, and crypto banking issuer comparison platform. It is completely distinct from and unaffiliated with the Ritual AI Layer-1 blockchain network (ritual.net) or the RITUAL cryptocurrency token.",
        knowsAbout: [
          "Crypto Debit Cards",
          "Self-Custody Smart Contract Wallets",
          "MiCA Stablecoin Compliance",
          "Electronic Money Institutions",
          "DeFi Collateralized Credit Lines",
        ],
        sameAs: site.socialLinks.length > 0 ? site.socialLinks : undefined,
      },
      {
        "@type": "WebSite",
        "@id": websiteId,
        url: site.url,
        name: `${site.name} — Web3 & Crypto Card Intelligence`,
        publisher: { "@id": orgId },
        potentialAction: {
          "@type": "SearchAction",
          target: { "@type": "EntryPoint", urlTemplate: `${site.url}/?q={search_term_string}` },
          "query-input": "required name=search_term_string",
        },
      },
      {
        "@type": "WebPage",
        "@id": pageUrl,
        url: pageUrl,
        name: post.title,
        description: post.excerpt,
        isPartOf: { "@id": websiteId },
        about: { "@id": articleId },
        primaryImageOfPage: image,
        breadcrumb: { "@id": `${pageUrl}#breadcrumb` },
        datePublished: post.publishedAt,
        dateModified: post.updatedAt,
      },
      {
        "@type": "BreadcrumbList",
        "@id": `${pageUrl}#breadcrumb`,
        itemListElement: [
          { "@type": "ListItem", position: 1, name: "Home", item: absoluteUrl("/") },
          { "@type": "ListItem", position: 2, name: "Blog", item: absoluteUrl("/blog") },
          { "@type": "ListItem", position: 3, name: post.title, item: pageUrl },
        ],
      },
      {
        "@type": "BlogPosting",
        "@id": articleId,
        headline: post.title,
        description: post.excerpt,
        url: pageUrl,
        mainEntityOfPage: { "@id": pageUrl },
        isPartOf: { "@id": pageUrl },
        datePublished: post.publishedAt,
        dateModified: post.updatedAt,
        image,
        author: { "@id": authorNode ? authorNode["@id"] : orgId },
        publisher: { "@id": orgId },
        mentions: cards.length > 0 ? cards.map((card) => ({ "@id": productId(card.slug) })) : undefined,
      },
      ...(authorNode ? [authorNode] : []),
      ...cards.map((card) => financialProductNode(card)),
      ...(cards.length > 0
        ? [
            {
              "@type": "ItemList",
              "@id": `${pageUrl}#cardlist`,
              name: `Cards featured in ${post.title}`,
              numberOfItems: cards.length,
              itemListElement: cards.map((card, index) => ({
                "@type": "ListItem",
                position: index + 1,
                name: card.name,
                url: absoluteUrl(`/crypto-card/${card.slug}`),
                item: { "@id": productId(card.slug) },
              })),
            },
          ]
        : []),
      ...(faqs.length > 0
        ? [
            {
              "@type": "FAQPage",
              "@id": `${pageUrl}#faq`,
              isPartOf: { "@id": articleId },
              mainEntity: faqs.map((faq) => ({
                "@type": "Question",
                name: faq.question,
                acceptedAnswer: { "@type": "Answer", text: faq.answer },
              })),
            },
          ]
        : []),
    ],
  };
}
